import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易尚氏学 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易尚氏学 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/031.md","filePath":"zh/classics/shangshi/031.md"}'),h={name:"zh/classics/shangshi/031.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>乾为大。乾阳上升。为民所止。故日大畜。阳为艮畜。故利于贞定也。兑为食。艮为家。皆在外。故不家食吉。坤为大川。上居坤水之颠。下履重阴。得行其志。故曰利涉大川。与颐上九之利涉大川同也。</p><p>彖曰。大畜刚健笃实辉光。日新其德。刚上而尚贤。能止健。大正也。不家食吉。养贤也。利涉大川。应乎天也。刚健笃实。谓乾。辉光谓艮。艮为日。故曰日新。艮为君子。故曰尚贤。曰养贤。五天位。上孚于五。故曰应乎天。</p><p>象曰。天在山中。大畜。君子以多识前言往行。以畜其德。</p><p>识。论语女以为多学而识之者钦。注识记也。乾为前。为言。为行。为德。艮止于下。故多识前言往行。以畜其德。艮为君子。</p><p>初九。有厉。利已。</p><p>厉危也。已止也。初有应。似利往。然二三皆阳。遇敌。故曰有厉。初勿用。故利已。言往应四则有灾也。旧解皆不知有厉之故在二三。于是虞氏命二变成坎。四在坎体。以取灾象。经义之晦。至于如此。真可叹也。</p><h3 id="象曰。有厉利已。不犯灾也。" tabindex="-1">象曰。有厉利已。不犯灾也。 <a class="header-anchor" href="#象曰。有厉利已。不犯灾也。" aria-label="Permalink to “象曰。有厉利已。不犯灾也。”">​</a></h3><p>不犯灾。释利已之故也。灾即厉。指二三。</p><p>九二。舆说輹。</p><p>伏坤为舆。震为輹。二应在五。五震体。乃舆在内。辕（右复）在外。故曰舆脱輹。车之行全恃輹。輹脱则车不能行。二承乘皆阳。阳遇阳则窒。故有是象。旧说以二应五。便谓利涉大川指二者非也。如二能利涉。焉有此象哉。然爻辞无吉凶。无咎悔。故象曰中无尤。言无尤之故。以得中也。</p><h3 id="象曰。舆说輹。中无尤也。" tabindex="-1">象曰。舆说輹。中无尤也。 <a class="header-anchor" href="#象曰。舆说輹。中无尤也。" aria-label="Permalink to “象曰。舆说輹。中无尤也。”">​</a></h3><p>九三。艮马逐。利艰贞。日闲舆卫。利有攸往。</p><p>乾为艮马。震为逐。三多惧。故利艰贞。乾为日。尔雅释诂。闲习也。诗秦风游于北园。四马即闲。传亦训闲为习。震为舆卫。日闲舆卫者。言车马已闲习。利于行也。三临重阴故行利。</p><h3 id="象曰。利有攸往。上合志也。" tabindex="-1">象曰。利有攸往。上合志也。 <a class="header-anchor" href="#象曰。利有攸往。上合志也。" aria-label="Permalink to “象曰。利有攸往。上合志也。”">​</a></h3><p>三遇重阴。阳遇阴则通。故曰上合志。上谓四五。此与升初六之上合志同。初六之上谓二三。阴遇阳则通。与阳遇阴同也。虞翻谓上为上爻。故易本一失。说无不误。</p><p>六四。 童牛之牿 元吉。</p><p>释文。童牛无角牛也。按太玄更次五云。童牛角马。不今不古。即谓牛无角也。牿释文云。陆作角。刘云牿之言角也。九家作告。云牛触。角着横木。所以告人。按刘陆作角者是也。骆牿角。音同通用。艮为牛。象失传。详焦氏易诂艮少故为童牛。而艮为角。四居艮初。有若初生之角。言小牛角初生也。四应初。故吉。</p><h3 id="象曰。六四元吉。有喜也。" tabindex="-1">象曰。六四元吉。有喜也。 <a class="header-anchor" href="#象曰。六四元吉。有喜也。" aria-label="Permalink to “象曰。六四元吉。有喜也。”">​</a></h3><p>应在初阳故有喜。庐浙云。说文牿牛马牢。牛在牢则范而不越。故吉。于艮止义亦合。</p><p>六五。豮豕之牙。吉。</p><p>尔雅释兽。豕子椭（左豕）豮。注云。俗呼小豮猪为堕（左豕）子。是豮豕为小豕艮少象也。二兑为牙。五应之。故曰豮豕之牙。言小豕初生牙也。按艮为黔喙。兽之黔喙者莫过于豕。疑艮或有豕象。又姤以巽为豕。大畜三至五伏巽。或仍以巽为豕也。李鼎作深知豮豕二字皆由象生。然求之不得。谓五应二。二坎爻为豕。非。又庐浙云坤雅以代（左木）系豕。谓之牙。牙者系之者也。系而不去故吉。亦与艮止义合。</p><h3 id="象日。六五之吉。有庆也。" tabindex="-1">象日。六五之吉。有庆也。 <a class="header-anchor" href="#象日。六五之吉。有庆也。" aria-label="Permalink to “象日。六五之吉。有庆也。”">​</a></h3><p>六五承阳。故有庆。晋六五。睽六五。皆上承阳。皆曰往有庆。兹与之同。</p><p>上九。何天之衢。亨。</p><p>艮一阳在上为天。又为背。故曰何。艮为道路。故曰何天之衢。左传昭二年尸诸周氏之衢。注衢道也。又尔雅释宫。四达谓之衢。何天之衢者。言阳在上不为所畜。通达之甚。象曰道大行。亦释衢为道。大行即谓其通达。虞翻释何为当，王弼竟释何为何乃。朱子取之。益非。盖皆以天衢如何负何为疑。岂知易辞皆摄取象之精神。而不能执其解。执则易辞无一可通。</p><h3 id="象曰。何天之衢。道大行也。" tabindex="-1">象曰。何天之衢。道大行也。 <a class="header-anchor" href="#象曰。何天之衢。道大行也。" aria-label="Permalink to “象曰。何天之衢。道大行也。”">​</a></h3><p>艮为天。易林豫之旅云。人天门。随之蹇云戴瓶望天。皆以艮为天。</p>',28)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
